<?php /** @var array $sites @var \Core\Security\Csrf $csrf */ $healthy=count(array_filter($sites,fn($s)=>$s['status']==='healthy')); $errors=count(array_filter($sites,fn($s)=>$s['status']==='error')); ?>
<div class="metric-grid"><div class="metric"><span>Managed sites</span><strong><?= count($sites) ?></strong><small>Registered installations</small></div><div class="metric"><span>Healthy</span><strong class="text-ok"><?= $healthy ?></strong><small>Latest authenticated check</small></div><div class="metric"><span>Needs attention</span><strong class="<?= $errors ? 'text-bad' : 'text-ok' ?>"><?= $errors ?></strong><small>Connection or site error</small></div></div>
<div class="card"><div class="card-heading"><div><h2>Client sites</h2><p class="muted">Monitor Website Core installations through their scoped <code>health.read</code> API key. Credentials are encrypted with this installation’s app key.</p></div></div>
<?php if (!$sites): ?><div class="empty-state">No managed sites yet.</div><?php else: ?><table><tr><th>Site</th><th>Remote identity</th><th>Versions</th><th>Status</th><th>Last checked</th><th></th></tr><?php foreach($sites as $site): $industries=json_decode((string)($site['industry_versions_json']??''),true)?:[]; ?><tr><td><strong><?= e($site['label']) ?></strong><br><a href="<?= e_url($site['base_url']) ?>" target="_blank" rel="noopener noreferrer"><?= e($site['base_url']) ?> ↗</a></td><td><?= e($site['remote_site'] ?? '—') ?></td><td><strong>Core <?= e($site['core_version'] ?? '—') ?></strong><?php foreach($industries as $industry): ?><br><small><?= e($industry['name']??'Industry') ?> <?= e($industry['version']??'') ?></small><?php endforeach; ?></td><td><span class="badge <?= $site['status']==='healthy'?'ok':($site['status']==='error'?'bad':'warn') ?>"><?= e($site['status']) ?></span><?php if($site['last_error']): ?><br><small class="err"><?= e($site['last_error']) ?></small><?php endif; ?></td><td><?= e($site['last_checked_at'] ?? 'Never') ?></td><td><form method="post" style="display:inline"><?= $csrf->field() ?><input type="hidden" name="action" value="check"><input type="hidden" name="id" value="<?= (int)$site['id'] ?>"><button class="btn small">Check now</button></form><form method="post" style="display:inline" onsubmit="return confirm('Remove this site from the agency dashboard?')"><?= $csrf->field() ?><input type="hidden" name="action" value="remove"><input type="hidden" name="id" value="<?= (int)$site['id'] ?>"><button class="btn small danger">Remove</button></form></td></tr><?php endforeach; ?></table><?php endif; ?></div>
<div class="card"><h2 style="margin-top:0">Add a managed site</h2><p class="muted">On the remote site, create a key under Integrations with the <code>health.read</code> scope. The key is encrypted here and never displayed again.</p><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="add"><div class="inline-fields"><div><label>Site label</label><input name="label" required placeholder="Acme Catering"></div><div><label>HTTPS site URL</label><input name="base_url" type="url" required placeholder="https://client.example.com"></div><div><label>Remote API key</label><input name="api_token" type="password" required autocomplete="new-password" placeholder="wcp_…"></div></div><button class="btn">Add site</button></form></div>
